const hashId = (str) => { let h = 2166136261; for (const ch of str) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; } return h; };
const KIND_OF = (base) => { const r = Array.isArray(base.render) ? base.render[0] : base.render; return r.kind === 'bodice' ? 'top' : r.kind; };
function pickDetails(base, id) {
  if (base.details) return base.details;
  const kind = KIND_OF(base);
  const pool = DETAIL_POOLS[kind];
  if (!pool || base.noDetails) return [];
  const h = hashId(id);
  const out = [];
  const d1 = pool[h % pool.length]; if (d1) out.push(d1);
  const d2 = pool[(h >>> 7) % pool.length]; if (d2 && d2 !== d1 && ((h >>> 15) & 3) === 0) out.push(d2);
  return out;
}

