/* ---------------- builder ---------------- */
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const clampN = (v, a, b) => Math.max(a, Math.min(b, v));
function mergeAes(...parts) {
  const out = {};
  for (const p of parts) for (const [k, v] of Object.entries(p || {})) out[k] = (out[k] || 0) + v;
  const total = Object.values(out).reduce((s, v) => s + v, 0) || 1;
  for (const k in out) out[k] = Math.round((out[k] / total) * 100) / 100;
  return out;
}
const CW_NAME = { babyPink: 'Baby Pink', lilacGrey: 'Lilac Grey', hotPink: 'Hot Pink', cherryBright: 'Bright Cherry', lightDenim: 'Light Denim' };
const cwName = (k) => CW_NAME[k] || k.charAt(0).toUpperCase() + k.slice(1);
const MAT_NAME = { cotton: '', satin: 'Satin', leather: 'Leather', knit: 'Knit', rib: 'Ribbed', wool: 'Wool', tweed: 'Bouclé', denim: 'Denim', nylon: 'Nylon', velvet: 'Velvet', sequin: 'Sequin', chrome: 'Chrome', lace: 'Lace', sheer: 'Tulle', fur: 'Faux Fur', latex: 'Latex', suede: 'Suede', canvas: 'Canvas' };
const PRINT_NAME = { stripe: 'Striped', pinstripe: 'Pinstripe', gingham: 'Gingham', plaid: 'Tartan', houndstooth: 'Houndstooth', leopard: 'Leopard', polka: 'Polka Dot', floral: 'Floral', argyle: 'Argyle', toile: 'Toile', camo: 'Camo', zebra: 'Zebra', logo: 'Logo' };

const PRINT_C2 = (cwKey) => { const t = COLORWAYS[cwKey]?.tier ?? 0; const hex = COLORWAYS[cwKey]?.hex || '#888'; return ['white', 'bone', 'oat', 'butter', 'ice', 'sky', 'babyPink', 'lilacGrey', 'pistachio'].includes(cwKey) ? '#2B2A2C' : t === 2 ? '#15110F' : '#F3F0E8'; };

export function buildVariant(base, cwKey, matKey, printKey, opts = {}) {
  const cw = COLORWAYS[cwKey] || COLORWAYS.ink;
  const mat = MATERIALS[matKey] || MATERIALS.cotton;
  const prt = printKey && printKey !== 'none' ? PRINTS[printKey] : null;
  const hex = cwKey === 'lightDenim' ? C.lightDenim : cw.hex;
  const id = opts.id || `${base.id}.${cwKey}.${matKey}${prt ? '.' + printKey : ''}`;
  const details = pickDetails(base, id);
  const trimKey = details.length ? (['white', 'bone', 'oat', 'butter', 'ice', 'sky', 'babyPink', 'lilacGrey', 'pistachio', 'rose'].includes(cwKey) ? (prt ? null : (hashId(id + 't') % 3 === 0 ? 'hotPink' : hashId(id + 't') % 3 === 1 ? 'gold' : null)) : (hashId(id + 't') % 4 === 0 ? 'white' : hashId(id + 't') % 4 === 1 ? 'gold' : null)) : null;
  const trimHex = trimKey ? (COLORWAYS[trimKey]?.hex || null) : null;
  const nameParts = [details[0] ? DETAIL_NAME[details[0]] : null, prt ? PRINT_NAME[printKey] : null, MAT_NAME[matKey] || null, base.name].filter(Boolean);
  const name = `${nameParts.join(' ')}${opts.setName ? '' : ` · ${cwName(cwKey)}`}`;
  const renderBase = Array.isArray(base.render) ? base.render.map((r) => ({ ...r })) : { ...base.render };
  const mainSpec = Array.isArray(renderBase) ? renderBase[0] : renderBase;
  if (details.length && mainSpec && !['makeup', 'hair'].includes(mainSpec.kind)) { mainSpec.details = details; if (trimHex) mainSpec.trim = trimHex; }
  const formality = clampN(base.formality + (mat.formal || 0) * (base.slot === 'shoes' || base.slot === 'bag' ? 0 : 1), 0, 6);
  const weight = clampN(base.weight + (mat.weight || 0), 1, 5);
  const metallic = METALS.includes(cwKey) || matKey === 'chrome';
  const statement = clampN((base.statement || 0) + (prt && (printKey === 'leopard' || printKey === 'zebra') ? 1 : 0) + (metallic && base.slot !== 'ears' && base.slot !== 'neck' && base.slot !== 'bracelet' ? 1 : 0), 0, 2);
  const iconPiece = base.icon || (statement === 2 && (metallic || matKey === 'sequin')) || (metallic && details.length >= 2 && prt);
  const rareScore = (prt ? 1 : 0) + (mat.price >= 1.5 ? 1 : 0) + (details.length >= 2 ? 1 : 0) + (cw.tier === 2 ? 1 : 0) + (base.statement === 2 ? 1 : 0);
  const rarity = opts.rarity || (iconPiece ? 'icon' : opts.set || metallic || matKey === 'sequin' || matKey === 'fur' || rareScore >= 3 ? 'archive' : rareScore === 2 ? 'edit' : 'core');
  const price = Math.round((base.price * (mat.price || 1) * (prt ? 1.25 : 1) * (1 + details.length * 0.08) * (cw.tier === 2 ? 1.6 : cw.tier === 1 ? 1.1 : 1)) / 10) * 10;
  const material = base.slot === 'makeup' ? null : (mat.render || (matKey === 'cotton' && base.cable ? 'cable' : null));
  const item = {
    id, base: base.id, slot: base.slot, name, house: base.house,
    color: hex, color2: prt ? PRINT_C2(cwKey) : (base.color2 || undefined), colors: prt ? [hex, PRINT_C2(cwKey)] : [hex],
    material: base.slot === 'makeup' ? undefined : (matKey === 'cotton' ? (base.cable ? 'cable' : undefined) : material || undefined),
    print: prt ? (prt.render || printKey) : undefined,
    render: renderBase,
    formality, weight, texture: base.slot === 'makeup' ? 'makeup' : (mat.texture || 'cotton'), shine: base.slot === 'makeup' ? 0 : (mat.shine || 0),
    volume: base.volume ?? 0, sharp: !!base.sharp, statement, hem: base.hem, heel: base.heel, toe: base.toe,
    metal: base.metal ? (cwKey === 'gold' ? 'gold' : 'silver') : null,
    aesthetics: mergeAes(base.aes, cw.aes, mat.aes, prt?.aes, ...details.map((d) => DETAIL_AES[d] || {})),
    rarity, source: opts.source || (rarity === 'core' || rarity === 'edit' ? 'atelier' : 'drop'),
    price, cw: cwKey, mat: matKey, prt: prt ? printKey : null, set: opts.set || null, opacity: base.opacity,
    swatches: swatchesFor(mat.texture || 'cotton', base.slot, matKey),
    details, trim: trimHex || undefined,
  };
  if (base.pim) item.pim = true;
  if (base.slot === 'makeup') { item.render = { ...base.render }; item.color = hex; item.colors = [hex]; }
  if (item.print && typeof item.render === 'object' && !Array.isArray(item.render) && item.render.kind === 'hosiery') { item.print = undefined; }
  return item;
}
function swatchesFor(texture, slot, matKey) {
  const n = ['dress', 'outer'].includes(slot) ? 3 : ['top', 'bottom', 'shoes', 'bag'].includes(slot) ? 2 : 1;
  const key = texture === 'metal' ? 'metal' : texture;
  return { [key]: n };
}

// One exclusive set per chapter, only from its secret level. Pieces are the bases that lean hardest to the chapter's
